import{_ as e,o as i,a as t,d as l}from"./chunks/framework.IehvnstE.js";const m=JSON.parse('{"title":"Сборки модов","description":"Сборки модов в Stuzhik — версионно-независимые наборы модов, которые можно применить к любому экземпляру одной кнопкой.","frontmatter":{"description":"Сборки модов в Stuzhik — версионно-независимые наборы модов, которые можно применить к любому экземпляру одной кнопкой.","head":[["meta",{"name":"keywords","content":"stuzhik сборки модов, стужик, mod collections, наборы модов minecraft, применить моды к экземпляру"}]]},"headers":[],"relativePath":"guide/collections.md","filePath":"guide/collections.md"}'),o={name:"guide/collections.md"};function r(n,a,h,s,d,c){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="сборки-модов" tabindex="-1">Сборки модов <a class="header-anchor" href="#сборки-модов" aria-label="Permalink to &quot;Сборки модов&quot;">​</a></h1><p>Свой набор модов без привязки к версии игры: собрали один раз и применяете к любому экземпляру, а Stuzhik сам подбирает подходящие версии модов.</p><p>Это не модпак: в сборке модов <strong>только список модов</strong>, которые вы обычно ставите вместе, без конфигов и настроек.</p><h2 id="зачем-это-нужно" tabindex="-1">Зачем это нужно <a class="header-anchor" href="#зачем-это-нужно" aria-label="Permalink to &quot;Зачем это нужно&quot;">​</a></h2><p>Модпак закрепляет версии, сборка модов нет. Если у вас есть привычный набор (скажем, оптимизация и QoL) и вы часто создаёте экземпляры под разные версии Minecraft, не нужно каждый раз ставить его заново руками: примените сборку модов, и <strong>версии подберутся под этот экземпляр сами</strong>.</p><h2 id="создание" tabindex="-1">Создание <a class="header-anchor" href="#создание" aria-label="Permalink to &quot;Создание&quot;">​</a></h2><h3 id="с-нуля" tabindex="-1">С нуля <a class="header-anchor" href="#с-нуля" aria-label="Permalink to &quot;С нуля&quot;">​</a></h3><ol><li>«Сборки модов» в боковой панели: впишите название в поле «Название сборки…» и нажмите «+» («Создать сборку»). С пустым полем «+» сам спросит название</li><li>Описание по желанию: карандаш «Изменить сборку» рядом с названием</li><li>Моды добавляются из встроенного каталога: переключатель «Каталог» над списком модов, у мода кнопка «В сборку». Поиск и фильтры такие же, как в обычном каталоге модов</li></ol><h3 id="из-установленного-экземпляра" tabindex="-1">Из установленного экземпляра <a class="header-anchor" href="#из-установленного-экземпляра" aria-label="Permalink to &quot;Из установленного экземпляра&quot;">​</a></h3><ol><li>«Сборки модов» → «Из экземпляра» → выберите экземпляр</li><li>Отметьте, какие моды взять (можно не все). В списке <strong>только моды с Modrinth и CurseForge</strong>: локальный JAR под другую версию игры не подобрать</li><li>Куда: «В новую сборку» (с названием) или «В «…»», в открытую сейчас сборку. Затем «Добавить»</li></ol><h2 id="применение" tabindex="-1">Применение <a class="header-anchor" href="#применение" aria-label="Permalink to &quot;Применение&quot;">​</a></h2><h3 id="к-готовому-экземпляру" tabindex="-1">К готовому экземпляру <a class="header-anchor" href="#к-готовому-экземпляру" aria-label="Permalink to &quot;К готовому экземпляру&quot;">​</a></h3><ol><li>Экземпляр → вкладка «Моды» → кнопка «Сборки модов» (подсказка «Применить»)</li><li>Выберите сборку модов</li><li>Stuzhik покажет предпросмотр: что установится, что пропустится (уже есть или несовместимо) и что не нашлось под эту версию или загрузчик</li><li>Подтвердите: «Установить выбранные»</li></ol><h3 id="при-создании-экземпляра" tabindex="-1">При создании экземпляра <a class="header-anchor" href="#при-создании-экземпляра" aria-label="Permalink to &quot;При создании экземпляра&quot;">​</a></h3><p>В форме создания экземпляра есть необязательное поле «Сборка модов» (оно появляется, когда у вас есть сборки модов, и не для ванильного экземпляра). <strong>Моды встанут сразу после создания</strong>, версии подберутся под его Minecraft и загрузчик.</p><h2 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h2><ul><li><strong>В модпак.</strong> Сборку модов можно выгрузить в <code>.mrpack</code> (Modrinth) или <code>.stzhk</code> (формат Stuzhik), закрепив версии под конкретную версию Minecraft</li><li><strong>Модпак в сборку модов.</strong> И наоборот: взять готовый модпак (Modrinth или CurseForge) и сохранить его список модов как сборку, не привязанную к версии</li></ul><h2 id="управление" tabindex="-1">Управление <a class="header-anchor" href="#управление" aria-label="Permalink to &quot;Управление&quot;">​</a></h2><ul><li><strong>Дубликат</strong>, чтобы сделать вариацию, не трогая оригинал</li><li><strong>Переименование и своя иконка</strong></li><li><strong>Сортировка модов</strong> внутри сборки: «По добавлению», «По названию» или «По источнику»</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li><a href="/guide/mods.html">Моды</a></li><li><a href="/guide/modpacks.html">Модпаки</a></li><li><a href="/faq.html">FAQ</a></li></ul>',21)])])}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
